const privacyHtml = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 \u2014 \u062a\u0637\u0628\u064a\u0642 \u0642\u0637\u0639\u0647 (Qata'ly)</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&family=Inter:wght@400;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --bg: #0A0E27;\n      --card-bg: #131B3E;\n      --card-border: #2A3875;\n      --accent-blue: #229ED9;\n      --accent-cyan: #38BDF8;\n      --accent-gold: #F59E0B;\n      --text-main: #FFFFFF;\n      --text-muted: #94A3B8;\n      --text-dim: #64748B;\n    }\n    * { margin: 0; padding: 0; box-sizing: border-box; }\n    body {\n      background-color: var(--bg);\n      color: var(--text-main);\n      font-family: 'Cairo', 'Inter', -apple-system, sans-serif;\n      line-height: 1.8;\n      padding: 0 16px 60px;\n    }\n    header {\n      max-width: 860px;\n      margin: 0 auto;\n      padding: 40px 0 24px;\n      text-align: center;\n      border-bottom: 2px solid var(--card-border);\n    }\n    .logo {\n      font-size: 38px;\n      font-weight: 900;\n      color: #fff;\n      display: inline-block;\n      margin-bottom: 8px;\n    }\n    .tagline {\n      color: var(--accent-cyan);\n      font-size: 15px;\n      font-weight: 700;\n    }\n    .nav-links {\n      display: flex;\n      justify-content: center;\n      gap: 12px;\n      margin-top: 20px;\n      flex-wrap: wrap;\n    }\n    .nav-links a {\n      color: var(--text-muted);\n      text-decoration: none;\n      font-size: 13px;\n      font-weight: 700;\n      padding: 6px 14px;\n      border: 1px solid var(--card-border);\n      border-radius: 8px;\n      background: var(--card-bg);\n      transition: all 0.2s;\n    }\n    .nav-links a:hover, .nav-links a.active {\n      color: #fff;\n      border-color: var(--accent-blue);\n      background: rgba(34, 158, 217, 0.15);\n    }\n    main {\n      max-width: 860px;\n      margin: 32px auto 0;\n    }\n    .meta-badge {\n      display: inline-block;\n      background: rgba(56, 189, 248, 0.12);\n      border: 1px solid rgba(56, 189, 248, 0.3);\n      color: var(--accent-cyan);\n      font-size: 12px;\n      font-weight: 700;\n      padding: 4px 12px;\n      border-radius: 6px;\n      margin-bottom: 20px;\n    }\n    h1 {\n      font-size: 28px;\n      font-weight: 900;\n      margin-bottom: 12px;\n      color: #fff;\n    }\n    h2 {\n      font-size: 20px;\n      font-weight: 800;\n      margin: 36px 0 14px;\n      color: var(--accent-cyan);\n      border-right: 4px solid var(--accent-blue);\n      padding-right: 12px;\n    }\n    h3 {\n      font-size: 16px;\n      font-weight: 700;\n      margin: 20px 0 8px;\n      color: #fff;\n    }\n    p, li {\n      color: var(--text-muted);\n      font-size: 15px;\n      margin-bottom: 14px;\n    }\n    ul, ol {\n      padding-right: 24px;\n      margin-bottom: 16px;\n    }\n    li { margin-bottom: 8px; }\n    .card {\n      background: var(--card-bg);\n      border: 1.5px solid var(--card-border);\n      border-radius: 14px;\n      padding: 24px;\n      margin: 20px 0;\n    }\n    .highlight-box {\n      background: rgba(245, 158, 11, 0.1);\n      border: 1.5px solid rgba(245, 158, 11, 0.4);\n      border-radius: 12px;\n      padding: 16px 20px;\n      margin: 20px 0;\n    }\n    .highlight-box p {\n      color: #FDE68A;\n      margin: 0;\n      font-size: 14px;\n    }\n    .contact-card {\n      background: #0f1631;\n      border: 2px solid var(--accent-blue);\n      border-radius: 14px;\n      padding: 24px;\n      text-align: center;\n      margin-top: 40px;\n    }\n    .contact-card a {\n      color: var(--accent-cyan);\n      font-weight: 700;\n      text-decoration: none;\n    }\n    footer {\n      max-width: 860px;\n      margin: 50px auto 0;\n      text-align: center;\n      font-size: 12px;\n      color: var(--text-dim);\n      border-top: 1px solid var(--card-border);\n      padding-top: 24px;\n    }\n  </style>\n</head>\n<body>\n\n  <header>\n    <div class=\"logo\">\u0642\u064e\u0637\u0652\u0639\u064e\u0644\u0650\u064a \u26a1 (Qata'ly)</div>\n    <div class=\"tagline\">\u0645\u062d\u0631\u0643 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u062a\u0643\u064a\u0641\u064a \u0644\u0642\u0637\u0639 \u0648\u0641\u0647\u0645 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u2014 \u0627\u0644\u062b\u0627\u0646\u0648\u064a\u0629 \u0627\u0644\u0639\u0627\u0645\u0629</div>\n    <nav class=\"nav-links\">\n      <a href=\"/functions/v1/legal\">\u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629</a>\n      <a href=\"/functions/v1/legal/privacy\" class=\"active\">\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629</a>\n      <a href=\"/functions/v1/legal/terms\">\u0634\u0631\u0648\u0637 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645</a>\n      <a href=\"/functions/v1/legal/delete-account\">\u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a</a>\n      <a href=\"/functions/v1/legal/licenses\">\u0627\u0644\u062a\u0631\u0627\u062e\u064a\u0635 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629</a>\n    </nav>\n  </header>\n\n  <main>\n    <span class=\"meta-badge\">\u062a\u0627\u0631\u064a\u062e \u0622\u062e\u0631 \u062a\u062d\u062f\u064a\u062b: 30 \u0623\u063a\u0633\u0637\u0633 2026</span>\n    <h1>\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 (Privacy Policy)</h1>\n\n    <p>\n      \u0623\u0647\u0644\u0627\u064b \u0628\u0643 \u0641\u064a \u062a\u0637\u0628\u064a\u0642 <strong>\u00ab\u0642\u0637\u0639\u0647\u00bb (Qata'ly)</strong>. \u0646\u062d\u0646 \u0646\u0644\u062a\u0632\u0645 \u0628\u062d\u0645\u0627\u064a\u0629 \u062e\u0635\u0648\u0635\u064a\u0629 \u0648\u0623\u0645\u0627\u0646 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0639\u0646\u062f \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0643 \u0644\u062a\u0637\u0628\u064a\u0642\u0646\u0627 \u0639\u0644\u0649 \u0646\u0638\u0627\u0645 \u0623\u0646\u062f\u0631\u0648\u064a\u062f (Google Play) \u0648\u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0647. \u062a\u0648\u0636\u062d \u0647\u0630\u0647 \u0627\u0644\u0648\u062b\u064a\u0642\u0629 \u0645\u0627\u0647\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u064a \u0646\u062c\u0645\u0639\u0647\u0627\u060c \u0643\u064a\u0641\u064a\u0629 \u0645\u0639\u0627\u0644\u062c\u062a\u0647\u0627\u060c \u0648\u0627\u0644\u062a\u062f\u0627\u0628\u064a\u0631 \u0627\u0644\u0645\u062a\u0628\u0639\u0629 \u0644\u062d\u0645\u0627\u064a\u062a\u0647\u0627 \u0648\u0641\u0642\u0627\u064b \u0644\u0645\u0639\u0627\u064a\u064a\u0631 \u0648\u0633\u064a\u0627\u0633\u0627\u062a \u0645\u062a\u062c\u0631 Google Play \u0648\u0642\u0648\u0627\u0646\u064a\u0646 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a.\n    </p>\n\n    <div class=\"highlight-box\">\n      <p>\u26a1 <strong>\u0645\u0644\u062e\u0635 \u0633\u0631\u064a\u0639:</strong> \u0646\u062d\u0646 \u0644\u0627 \u0646\u0628\u064a\u0639 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0644\u0623\u064a \u0637\u0631\u0641 \u062b\u0627\u0644\u062b\u060c \u0648\u0644\u0627 \u0646\u0633\u062a\u062e\u062f\u0645 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0644\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0648\u062c\u0647\u0629. \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u062a\u064f\u0633\u062a\u062e\u062f\u0645 \u062d\u0635\u0631\u064a\u0627\u064b \u0644\u062d\u0641\u0638 \u062a\u0642\u062f\u0645\u0643 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u060c \u0648\u062a\u062e\u0635\u064a\u0635 \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u0642\u0637\u0639 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0648\u0641\u0642\u0627\u064b \u0644\u0645\u0633\u062a\u0648\u0627\u0643.</p>\n    </div>\n\n    <h2>1. \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u064a \u0646\u0642\u0648\u0645 \u0628\u062c\u0645\u0639\u0647\u0627</h2>\n    <div class=\"card\">\n      <h3>\u0623. \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062a\u0648\u062b\u064a\u0642 (Account & Authentication):</h3>\n      <ul>\n        <li><strong>\u0645\u0639\u0631\u0641 \u0627\u0644\u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 (Telegram ID):</strong> \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0644\u0625\u0646\u0634\u0627\u0621 \u0648\u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u062c\u0644\u0633\u0629 \u0628\u0623\u0645\u0627\u0646 \u0628\u062f\u0648\u0646 \u0627\u0644\u062d\u0627\u062c\u0629 \u0644\u0643\u0644\u0645\u0627\u062a \u0645\u0631\u0648\u0631 \u0645\u0639\u0642\u062f\u0629.</li>\n        <li><strong>\u0627\u0644\u0627\u0633\u0645 \u0648\u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0623\u062e\u064a\u0631 \u0648\u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645:</strong> \u0627\u0644\u0645\u0639\u0631\u0648\u0636 \u0641\u064a \u0644\u0648\u062d\u0629 \u0627\u0644\u0635\u062f\u0627\u0631\u0629 (Leaderboard) \u0648\u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0634\u062e\u0635\u064a \u0644\u0644\u062a\u0644\u0645\u064a\u0630.</li>\n        <li><strong>\u0627\u0644\u0635\u0648\u0631\u0629 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a):</strong> \u0635\u0648\u0631\u0629 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0634\u062e\u0635\u064a \u0627\u0644\u0645\u0623\u062e\u0648\u0630\u0629 \u0645\u0646 \u062d\u0633\u0627\u0628 \u0627\u0644\u062a\u0644\u064a\u062c\u0631\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629.</li>\n      </ul>\n\n      <h3>\u0628. \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0646\u0634\u0627\u0637 \u0648\u0627\u0644\u062a\u0642\u062f\u0645 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a (Educational Progress Data):</h3>\n      <ul>\n        <li><strong>\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0647\u0627\u0631\u0629 \u0648\u0627\u0644\u062a\u0642\u064a\u064a\u0645 (MMR):</strong> \u0646\u0642\u0627\u0637 \u0627\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u062a\u064a \u062a\u062d\u062f\u062f \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u0642\u0637\u0639 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0643.</li>\n        <li><strong>\u0633\u062c\u0644 \u0627\u0644\u062a\u062f\u0631\u064a\u0628\u0627\u062a \u0648\u0627\u0644\u062d\u0644\u0648\u0644:</strong> \u0627\u0644\u0625\u062c\u0627\u0628\u0627\u062a\u060c \u0627\u0644\u062f\u0631\u062c\u0627\u062a\u060c \u0648\u0648\u0642\u062a \u062d\u0644 \u0627\u0644\u0642\u0637\u0639 \u0644\u0627\u062d\u062a\u0633\u0627\u0628 \u0627\u0644\u062f\u0642\u0629 \u0648\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u062a\u0642\u064a\u064a\u0645.</li>\n        <li><strong>\u0642\u0627\u0645\u0648\u0633 \u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0635\u0639\u0628\u0629 (Vocabulary Weaknesses):</strong> \u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0627\u0644\u062a\u064a \u0623\u062e\u0637\u0623\u062a \u0641\u064a\u0647\u0627 \u0644\u064a\u0642\u0648\u0645 \u0627\u0644\u0646\u0638\u0627\u0645 \u0628\u0625\u0639\u0627\u062f\u0629 \u062a\u062f\u0631\u064a\u0628\u0643 \u0639\u0644\u064a\u0647\u0627.</li>\n        <li><strong>\u0627\u0644\u062a\u062a\u0627\u0628\u0639 \u0627\u0644\u064a\u0648\u0645\u064a (Daily Streak):</strong> \u0644\u062d\u0633\u0627\u0628 \u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0645\u062a\u0648\u0627\u0635\u0644\u0629 \u0648\u062a\u0634\u062c\u064a\u0639\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629.</li>\n      </ul>\n\n      <h3>\u062c. \u0646\u0635\u0648\u0635 \u0645\u0642\u0627\u0644\u0627\u062a \u0627\u0644\u062a\u0639\u0628\u064a\u0631 (Writing/Journal Entries):</h3>\n      <ul>\n        <li>\u0627\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0627\u0644\u062a\u064a \u064a\u0643\u062a\u0628\u0647\u0627 \u0627\u0644\u0637\u0627\u0644\u0628 \u0641\u064a \u0642\u0633\u0645 \u0627\u0644\u064a\u0648\u0645\u064a\u0627\u062a (Journal) \u0628\u063a\u0631\u0636 \u062a\u0635\u062d\u064a\u062d\u0647\u0627 \u0644\u063a\u0648\u064a\u0627\u064b \u0648\u0625\u0645\u0644\u0627\u0626\u064a\u0627\u064b \u0628\u0648\u0627\u0633\u0637\u0629 \u062e\u0648\u0627\u0631\u0632\u0645\u064a\u0627\u062a \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a.</li>\n      </ul>\n    </div>\n\n    <h2>2. \u0643\u064a\u0641 \u0646\u0633\u062a\u062e\u062f\u0645 \u0628\u064a\u0627\u0646\u0627\u062a\u0643\u061f</h2>\n    <p>\u062a\u064f\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062a\u0645 \u062c\u0645\u0639\u0647\u0627 \u0644\u0644\u0623\u063a\u0631\u0627\u0636 \u0627\u0644\u062a\u0627\u0644\u064a\u0629 \u0641\u0642\u0637:</p>\n    <ol>\n      <li><strong>\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062e\u062f\u0645\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629:</strong> \u062a\u0648\u0644\u064a\u062f \u0642\u0637\u0639 \u0641\u0647\u0645 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u062a\u0646\u0627\u0633\u0628 \u0645\u0633\u062a\u0648\u0649 \u0643\u0644 \u0637\u0627\u0644\u0628 \u0627\u0644\u0641\u0631\u062f\u064a.</li>\n      <li><strong>\u062a\u062a\u0628\u0639 \u0627\u0644\u062a\u0642\u062f\u0645 \u0627\u0644\u062f\u0631\u0627\u0633\u064a:</strong> \u0639\u0631\u0636 \u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u062f\u0642\u0629\u060c \u0646\u0642\u0627\u0637 \u0627\u0644\u0642\u0648\u0629\u060c \u0648\u0642\u0627\u0645\u0648\u0633 \u0627\u0644\u0636\u0639\u0641 \u0627\u0644\u0634\u062e\u0635\u064a.</li>\n      <li><strong>\u0644\u0648\u062d\u0629 \u0627\u0644\u0634\u0631\u0641 \u0648\u0627\u0644\u062a\u0646\u0627\u0641\u0633\u064a\u0629:</strong> \u0639\u0631\u0636 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0637\u0644\u0627\u0628 \u0627\u0644\u0645\u062a\u0641\u0648\u0642\u064a\u0646 \u0641\u064a \u0641\u0635\u0648\u0644\u0647\u0645 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629 \u0648\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062c\u0645\u0647\u0648\u0631\u064a\u0629.</li>\n      <li><strong>\u0623\u0645\u0627\u0646 \u0627\u0644\u062d\u0633\u0627\u0628:</strong> \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0635\u062d\u0629 \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0648\u0645\u0646\u0639 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0644\u064a \u0623\u0648 \u063a\u064a\u0631 \u0627\u0644\u0645\u0635\u0631\u062d \u0628\u0647.</li>\n    </ol>\n\n    <h2>3. \u0627\u0644\u062e\u062f\u0645\u0627\u062a \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0629 \u0648\u0627\u0644\u0623\u0637\u0631\u0627\u0641 \u0627\u0644\u062b\u0627\u0644\u062b\u0629 (Third-Party Services)</h2>\n    <p>\u064a\u0639\u062a\u0645\u062f \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0639\u0644\u0649 \u0634\u0631\u0643\u0627\u0621 \u0645\u0648\u062b\u0648\u0642\u064a\u0646 \u0644\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062e\u062f\u0645\u0629 \u0628\u0623\u0639\u0644\u0649 \u062f\u0631\u062c\u0627\u062a \u0627\u0644\u0643\u0641\u0627\u0621\u0629 \u0648\u0627\u0644\u0623\u0645\u0627\u0646:</p>\n    <div class=\"card\">\n      <ul>\n        <li><strong>Supabase (\u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0627\u0644\u062a\u0648\u062b\u064a\u0642):</strong> \u0627\u0633\u062a\u0636\u0627\u0641\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u062d\u0641\u0638 \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0648\u062a\u0637\u0628\u064a\u0642 \u0633\u064a\u0627\u0633\u0627\u062a \u0627\u0644\u0623\u0645\u0627\u0646 \u0627\u0644\u0645\u0634\u062f\u062f\u0629 (Row-Level Security) \u0648\u0627\u0644\u062a\u0634\u0641\u064a\u0631 \u0639\u0628\u0631 \u0628\u0631\u0648\u062a\u0648\u0643\u0648\u0644 TLS.</li>\n        <li><strong>Google AI Studio (Gemini Models):</strong> \u0645\u0639\u0627\u0644\u062c\u0629 \u0646\u0635\u0648\u0635 \u0627\u0644\u0642\u0637\u0639 \u0648\u062a\u0648\u0644\u064a\u062f \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0648\u0627\u0644\u062a\u0635\u062d\u064a\u062d \u0627\u0644\u0644\u063a\u0648\u064a (\u064a\u062a\u0645 \u0625\u0631\u0633\u0627\u0644 \u0633\u064a\u0627\u0642 \u0627\u0644\u0633\u0624\u0627\u0644 \u0648\u0627\u0644\u0645\u0648\u0636\u0648\u0639 \u0641\u0642\u0637 \u062f\u0648\u0646 \u0631\u0628\u0637\u0647 \u0628\u0647\u0648\u064a\u062a\u0643 \u0627\u0644\u0634\u062e\u0635\u064a\u0629).</li>\n        <li><strong>Groq Cloud (LPU Inference):</strong> \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u062a\u0648\u0644\u064a\u062f \u0627\u0644\u0641\u0648\u0631\u064a \u0627\u0644\u0633\u0631\u064a\u0639 \u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0627\u0644\u062a\u0631\u062c\u0645\u0629 \u0627\u0644\u0645\u0639\u062c\u0645\u064a\u0629.</li>\n        <li><strong>Telegram Login Widget:</strong> \u0648\u0633\u064a\u0644\u0629 \u0627\u0644\u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u0622\u0645\u0646\u0629 \u0627\u0644\u0645\u0639\u062a\u0645\u062f\u0629 \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0647\u0648\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645.</li>\n      </ul>\n    </div>\n\n    <h2>4. \u0623\u0645\u0627\u0646 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0627\u0644\u062a\u0634\u0641\u064a\u0631 (Data Security)</h2>\n    <p>\n      \u0646\u062d\u0646 \u0646\u062a\u062e\u0630 \u062a\u062f\u0627\u0628\u064a\u0631 \u0623\u0645\u0646\u064a\u0629 \u0635\u0627\u0631\u0645\u0629 \u0648\u0645\u0637\u0627\u0628\u0642\u0629 \u0644\u0645\u0639\u0627\u064a\u064a\u0631 \u0627\u0644\u0635\u0646\u0627\u0639\u0629 \u0644\u062d\u0645\u0627\u064a\u0629 \u0628\u064a\u0627\u0646\u0627\u062a\u0643:\n    </p>\n    <ul>\n      <li>\u062c\u0645\u064a\u0639 \u0627\u0644\u0627\u062a\u0635\u0627\u0644\u0627\u062a \u0628\u064a\u0646 \u062a\u0637\u0628\u064a\u0642 \u0642\u0637\u0639\u0647 \u0648\u062e\u0648\u0627\u062f\u0645 \u0627\u0644\u0628\u0627\u0643 \u0627\u0646\u062f \u0645\u0634\u0641\u0631\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0639\u0628\u0631 \u0628\u0631\u0648\u062a\u0648\u0643\u0648\u0644\u0627\u062a HTTPS / TLS 1.3.</li>\n      <li>\u062a\u0637\u0628\u064a\u0642 \u0633\u064a\u0627\u0633\u0627\u062a \u0623\u0645\u0627\u0646 \u0645\u062a\u0642\u062f\u0645\u0629 \u0639\u0644\u0649 \u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a (Row-Level Security - RLS) \u062a\u0636\u0645\u0646 \u0639\u062f\u0645 \u0642\u062f\u0631\u0629 \u0623\u064a \u0645\u0633\u062a\u062e\u062f\u0645 \u0639\u0644\u0649 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0645\u0633\u062a\u062e\u062f\u0645 \u0622\u062e\u0631.</li>\n      <li>\u0639\u062f\u0645 \u062a\u062e\u0632\u064a\u0646 \u0623\u064a \u0643\u0644\u0645\u0627\u062a \u0645\u0631\u0648\u0631 \u062d\u0633\u0627\u0633\u0629 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0639\u0644\u0649 \u062e\u0648\u0627\u062f\u0645\u0646\u0627.</li>\n    </ul>\n\n    <h2>5. \u062e\u0635\u0648\u0635\u064a\u0629 \u0627\u0644\u0637\u0644\u0627\u0628 \u0648\u0627\u0644\u0623\u0637\u0641\u0627\u0644 (Children's Privacy - COPPA / GDPR)</h2>\n    <p>\n      \u062a\u0637\u0628\u064a\u0642 \u00ab\u0642\u0637\u0639\u0647\u00bb \u0645\u0648\u062c\u0647 \u0644\u0637\u0644\u0627\u0628 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062b\u0627\u0646\u0648\u064a\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0648\u0627\u0644\u0634\u0647\u0627\u062f\u0627\u062a \u0627\u0644\u0645\u0639\u0627\u062f\u0644\u0629 (\u0627\u0644\u0623\u0639\u0645\u0627\u0631 \u0645\u0646 13 \u0639\u0627\u0645\u0627\u064b \u0641\u0645\u0627 \u0641\u0648\u0642). \u0646\u062d\u0646 \u0644\u0627 \u0646\u062c\u0645\u0639 \u0639\u0646 \u0639\u0645\u062f \u0623\u064a \u0628\u064a\u0627\u0646\u0627\u062a \u062a\u0639\u0631\u064a\u0641\u064a\u0629 \u0634\u062e\u0635\u064a\u0629 \u0645\u0646 \u0623\u0637\u0641\u0627\u0644 \u062f\u0648\u0646 \u0633\u0646 13 \u0639\u0627\u0645\u0627\u064b. \u0625\u0630\u0627 \u0639\u0644\u0645\u062a \u0623\u0646 \u0637\u0641\u0644\u0627\u064b \u062f\u0648\u0646 \u0633\u0646 13 \u0642\u062f \u0632\u0648\u062f\u0646\u0627 \u0628\u0628\u064a\u0627\u0646\u0627\u062a \u0634\u062e\u0635\u064a\u0629\u060c \u064a\u0631\u062c\u0649 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627 \u0644\u062d\u0630\u0641\u0647\u0627 \u0641\u0648\u0631\u0627\u064b.\n    </p>\n\n    <h2>6. \u062d\u0642\u0648\u0642 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u062d\u0630\u0641 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a (User Rights & Deletion)</h2>\n    <p>\n      \u064a\u062d\u0642 \u0644\u0643 \u0641\u064a \u0623\u064a \u0648\u0642\u062a:\n    </p>\n    <ul>\n      <li><strong>\u0627\u0644\u0627\u0637\u0644\u0627\u0639 \u0639\u0644\u0649 \u0628\u064a\u0627\u0646\u0627\u062a\u0643:</strong> \u0645\u0631\u0627\u062c\u0639\u0629 \u0643\u0627\u0641\u0629 \u062f\u0631\u062c\u0627\u062a\u0643 \u0648\u0633\u062c\u0644 \u0643\u0644\u0645\u0627\u062a\u0643 \u0639\u0628\u0631 \u0645\u0644\u0641\u0643 \u0627\u0644\u0634\u062e\u0635\u064a \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642.</li>\n      <li><strong>\u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0646\u0647\u0627\u0626\u064a\u0627\u064b (Right to Erasure):</strong> \u064a\u0645\u0643\u0646\u0643 \u0637\u0644\u0628 \u062d\u0630\u0641 \u062d\u0633\u0627\u0628\u0643 \u0648\u0643\u0627\u0641\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0647 \u0641\u0648\u0631\u0627\u064b \u0633\u0648\u0627\u0621 \u0645\u0646 \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0639\u0628\u0631 \u0635\u0641\u062d\u0629 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0623\u0648 \u0639\u0628\u0631 \u0635\u0641\u062d\u0629 \u0627\u0644\u0648\u064a\u0628 \u0627\u0644\u0645\u062e\u0635\u0635\u0629: <a href=\"/functions/v1/legal/delete-account\" style=\"color: var(--accent-cyan); font-weight: bold;\">\u0637\u0644\u0628 \u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628</a>.</li>\n    </ul>\n\n    <h2>7. \u0627\u0644\u062a\u0639\u062f\u064a\u0644\u0627\u062a \u0639\u0644\u0649 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629</h2>\n    <p>\n      \u0642\u062f \u0646\u0642\u0648\u0645 \u0628\u062a\u062d\u062f\u064a\u062b \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 \u0647\u0630\u0647 \u0645\u0646 \u062d\u064a\u0646 \u0644\u0622\u062e\u0631 \u0644\u0645\u0648\u0627\u0643\u0628\u0629 \u0627\u0644\u062a\u062d\u062f\u064a\u062b\u0627\u062a \u0627\u0644\u062a\u0642\u0646\u064a\u0629 \u0623\u0648 \u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629. \u0633\u064a\u062a\u0645 \u0625\u0634\u0639\u0627\u0631 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0628\u0623\u064a \u062a\u063a\u064a\u064a\u0631\u0627\u062a \u062c\u0648\u0647\u0631\u064a\u0629 \u0639\u0628\u0631 \u0646\u0634\u0631 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0645\u062d\u062f\u062b\u0629 \u0639\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062d\u0629 \u0648\u062a\u062d\u062f\u064a\u062b \u062a\u0627\u0631\u064a\u062e \"\u0622\u062e\u0631 \u062a\u062d\u062f\u064a\u062b\".\n    </p>\n\n    <div class=\"contact-card\">\n      <h3 style=\"color: #fff; margin-bottom: 8px;\">\u0647\u0644 \u0644\u062f\u064a\u0643 \u0623\u064a \u0627\u0633\u062a\u0641\u0633\u0627\u0631 \u062d\u0648\u0644 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629\u061f</h3>\n      <p style=\"margin-bottom: 12px;\">\u0641\u0631\u064a\u0642 \u062a\u0637\u0648\u064a\u0631 \u0642\u0637\u0639\u0647 \u062c\u0627\u0647\u0632 \u0644\u0644\u0625\u062c\u0627\u0628\u0629 \u0639\u0644\u0649 \u062c\u0645\u064a\u0639 \u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a\u0643 \u0627\u0644\u0623\u0645\u0646\u064a\u0629 \u0648\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629:</p>\n      <p style=\"font-size: 16px;\">\n        \ud83d\udce7 \u0627\u0644\u0628\u0631\u064a\u062f \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a: <a href=\"mailto:support@qataly.app\">support@qataly.app</a><br>\n        \ud83d\udc68\u200d\ud83d\udcbb \u0645\u0633\u0624\u0648\u0644 \u0627\u0644\u062a\u0637\u0648\u064a\u0631: <a href=\"mailto:mmooup67@gmail.com\">mmooup67@gmail.com</a>\n      </p>\n    </div>\n  </main>\n\n  <footer>\n    <p>\u00a9 2026 \u062a\u0637\u0628\u064a\u0642 \u0642\u064e\u0637\u0652\u0639\u064e\u0644\u0650\u064a (Qata'ly). \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0642\u0648\u0642 \u0645\u062d\u0641\u0648\u0638\u0629 \u2014 \u062a\u0637\u0648\u064a\u0631 zed32 devs / abo wehidy</p>\n  </footer>\n\n</body>\n</html>\n";
const termsHtml = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>\u0634\u0631\u0648\u0637 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0648\u0627\u0644\u062e\u062f\u0645\u0629 \u2014 \u062a\u0637\u0628\u064a\u0642 \u0642\u0637\u0639\u0647 (Qata'ly)</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&family=Inter:wght@400;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --bg: #0A0E27;\n      --card-bg: #131B3E;\n      --card-border: #2A3875;\n      --accent-blue: #229ED9;\n      --accent-cyan: #38BDF8;\n      --accent-gold: #F59E0B;\n      --text-main: #FFFFFF;\n      --text-muted: #94A3B8;\n      --text-dim: #64748B;\n    }\n    * { margin: 0; padding: 0; box-sizing: border-box; }\n    body {\n      background-color: var(--bg);\n      color: var(--text-main);\n      font-family: 'Cairo', 'Inter', -apple-system, sans-serif;\n      line-height: 1.8;\n      padding: 0 16px 60px;\n    }\n    header {\n      max-width: 860px;\n      margin: 0 auto;\n      padding: 40px 0 24px;\n      text-align: center;\n      border-bottom: 2px solid var(--card-border);\n    }\n    .logo {\n      font-size: 38px;\n      font-weight: 900;\n      color: #fff;\n      display: inline-block;\n      margin-bottom: 8px;\n    }\n    .tagline {\n      color: var(--accent-cyan);\n      font-size: 15px;\n      font-weight: 700;\n    }\n    .nav-links {\n      display: flex;\n      justify-content: center;\n      gap: 12px;\n      margin-top: 20px;\n      flex-wrap: wrap;\n    }\n    .nav-links a {\n      color: var(--text-muted);\n      text-decoration: none;\n      font-size: 13px;\n      font-weight: 700;\n      padding: 6px 14px;\n      border: 1px solid var(--card-border);\n      border-radius: 8px;\n      background: var(--card-bg);\n      transition: all 0.2s;\n    }\n    .nav-links a:hover, .nav-links a.active {\n      color: #fff;\n      border-color: var(--accent-blue);\n      background: rgba(34, 158, 217, 0.15);\n    }\n    main {\n      max-width: 860px;\n      margin: 32px auto 0;\n    }\n    .meta-badge {\n      display: inline-block;\n      background: rgba(56, 189, 248, 0.12);\n      border: 1px solid rgba(56, 189, 248, 0.3);\n      color: var(--accent-cyan);\n      font-size: 12px;\n      font-weight: 700;\n      padding: 4px 12px;\n      border-radius: 6px;\n      margin-bottom: 20px;\n    }\n    h1 {\n      font-size: 28px;\n      font-weight: 900;\n      margin-bottom: 12px;\n      color: #fff;\n    }\n    h2 {\n      font-size: 20px;\n      font-weight: 800;\n      margin: 36px 0 14px;\n      color: var(--accent-cyan);\n      border-right: 4px solid var(--accent-blue);\n      padding-right: 12px;\n    }\n    h3 {\n      font-size: 16px;\n      font-weight: 700;\n      margin: 20px 0 8px;\n      color: #fff;\n    }\n    p, li {\n      color: var(--text-muted);\n      font-size: 15px;\n      margin-bottom: 14px;\n    }\n    ul, ol {\n      padding-right: 24px;\n      margin-bottom: 16px;\n    }\n    li { margin-bottom: 8px; }\n    .card {\n      background: var(--card-bg);\n      border: 1.5px solid var(--card-border);\n      border-radius: 14px;\n      padding: 24px;\n      margin: 20px 0;\n    }\n    .highlight-box {\n      background: rgba(34, 158, 217, 0.1);\n      border: 1.5px solid rgba(34, 158, 217, 0.4);\n      border-radius: 12px;\n      padding: 16px 20px;\n      margin: 20px 0;\n    }\n    .highlight-box p {\n      color: #BAE6FD;\n      margin: 0;\n      font-size: 14px;\n    }\n    .contact-card {\n      background: #0f1631;\n      border: 2px solid var(--accent-blue);\n      border-radius: 14px;\n      padding: 24px;\n      text-align: center;\n      margin-top: 40px;\n    }\n    .contact-card a {\n      color: var(--accent-cyan);\n      font-weight: 700;\n      text-decoration: none;\n    }\n    footer {\n      max-width: 860px;\n      margin: 50px auto 0;\n      text-align: center;\n      font-size: 12px;\n      color: var(--text-dim);\n      border-top: 1px solid var(--card-border);\n      padding-top: 24px;\n    }\n  </style>\n</head>\n<body>\n\n  <header>\n    <div class=\"logo\">\u0642\u064e\u0637\u0652\u0639\u064e\u0644\u0650\u064a \u26a1 (Qata'ly)</div>\n    <div class=\"tagline\">\u0634\u0631\u0648\u0637 \u0627\u0644\u062e\u062f\u0645\u0629 \u0648\u0627\u0644\u0627\u062a\u0641\u0627\u0642\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629</div>\n    <nav class=\"nav-links\">\n      <a href=\"/functions/v1/legal\">\u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629</a>\n      <a href=\"/functions/v1/legal/privacy\">\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629</a>\n      <a href=\"/functions/v1/legal/terms\" class=\"active\">\u0634\u0631\u0648\u0637 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645</a>\n      <a href=\"/functions/v1/legal/delete-account\">\u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a</a>\n      <a href=\"/functions/v1/legal/licenses\">\u0627\u0644\u062a\u0631\u0627\u062e\u064a\u0635 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629</a>\n    </nav>\n  </header>\n\n  <main>\n    <span class=\"meta-badge\">\u062a\u0627\u0631\u064a\u062e \u0622\u062e\u0631 \u062a\u062d\u062f\u064a\u062b: 30 \u0623\u063a\u0633\u0637\u0633 2026</span>\n    <h1>\u0634\u0631\u0648\u0637 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 (Terms of Service)</h1>\n\n    <p>\n      \u0645\u0631\u062d\u0628\u0627\u064b \u0628\u0643 \u0641\u064a \u062a\u0637\u0628\u064a\u0642 <strong>\u00ab\u0642\u0637\u0639\u0647\u00bb (Qata'ly)</strong>. \u064a\u064f\u0631\u062c\u0649 \u0642\u0631\u0627\u0621\u0629 \u0634\u0631\u0648\u0637 \u0627\u0644\u062e\u062f\u0645\u0629 \u0647\u0630\u0647 \u0628\u0639\u0646\u0627\u064a\u0629 \u0642\u0628\u0644 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642. \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0643 \u0644\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u0648 \u0625\u0646\u0634\u0627\u0621 \u062d\u0633\u0627\u0628 \u064a\u0639\u062f \u0645\u0648\u0627\u0641\u0642\u0629 \u0635\u0631\u064a\u062d\u0629 \u0648\u0643\u0627\u0645\u0644\u0629 \u0645\u0646\u0643 \u0639\u0644\u0649 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0648\u0637 \u0648\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 \u0627\u0644\u0645\u0644\u062d\u0642\u0629 \u0628\u0647\u0627.\n    </p>\n\n    <div class=\"highlight-box\">\n      <p>\ud83d\udca1 <strong>\u0627\u0644\u0647\u062f\u0641 \u0645\u0646 \u0627\u0644\u062a\u0637\u0628\u064a\u0642:</strong> \u0642\u0637\u0639\u0647 \u0647\u064a \u0645\u0646\u0635\u0629 \u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0645\u0628\u062a\u0643\u0631\u0629 \u062a\u0647\u062f\u0641 \u0625\u0644\u0649 \u062a\u062f\u0631\u064a\u0628 \u0648\u062a\u0637\u0648\u064a\u0631 \u0645\u0647\u0627\u0631\u0627\u062a \u0637\u0644\u0627\u0628 \u0627\u0644\u062b\u0627\u0646\u0648\u064a\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0641\u064a \u0642\u0631\u0627\u0621\u0629 \u0648\u0641\u0647\u0645 \u0642\u0637\u0639 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0648\u0627\u062c\u062a\u064a\u0627\u0632 \u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0627\u0644\u0641\u0647\u0645 \u0627\u0644\u0642\u0631\u0627\u0626\u064a \u0628\u0643\u0641\u0627\u0621\u0629 \u0639\u0627\u0644\u064a\u0629 \u0639\u0628\u0631 \u062e\u0648\u0627\u0631\u0632\u0645\u064a\u0627\u062a \u0627\u0644\u062a\u0643\u064a\u0641 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a.</p>\n    </div>\n\n    <h2>1. \u0623\u0647\u0644\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0648\u0627\u0644\u062a\u0633\u062c\u064a\u0644</h2>\n    <div class=\"card\">\n      <ul>\n        <li>\u064a\u064f\u062a\u0627\u062d \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0644\u0637\u0644\u0627\u0628 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062b\u0627\u0646\u0648\u064a\u0629 \u0648\u0627\u0644\u0645\u0647\u062a\u0645\u064a\u0646 \u0628\u062a\u0639\u0644\u0645 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0644\u0645\u0646 \u064a\u0628\u0644\u063a\u0648\u0646 13 \u0639\u0627\u0645\u0627\u064b \u0641\u0645\u0627 \u0641\u0648\u0642.</li>\n        <li>\u064a\u062a\u0645 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0648\u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0647\u0648\u064a\u0629 \u0639\u0628\u0631 \u0645\u0646\u0635\u0629 Telegram \u0628\u0634\u0643\u0644 \u0631\u0633\u0645\u064a \u0648\u0622\u0645\u0646.</li>\n        <li>\u0623\u0646\u062a \u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0633\u0631\u064a\u0629 \u0648\u0635\u0648\u0644\u0643 \u0644\u062d\u0633\u0627\u0628\u0643 \u0648\u0623\u064a \u0646\u0634\u0627\u0637 \u064a\u062a\u0645 \u0645\u0646 \u062e\u0644\u0627\u0644\u0647.</li>\n      </ul>\n    </div>\n\n    <h2>2. \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0645\u0642\u0628\u0648\u0644 \u0648\u0627\u0644\u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u062d\u0638\u0648\u0631</h2>\n    <p>\u0639\u0646\u062f \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0643 \u0644\u062a\u0637\u0628\u064a\u0642 \u00ab\u0642\u0637\u0639\u0647\u00bb\u060c \u0641\u0625\u0646\u0643 \u062a\u0648\u0627\u0641\u0642 \u0639\u0644\u0649 \u0627\u0644\u0627\u0645\u062a\u0646\u0627\u0639 \u0639\u0646:</p>\n    <ul>\n      <li>\u0645\u062d\u0627\u0648\u0644\u0629 \u0627\u062e\u062a\u0631\u0627\u0642 \u0623\u0648 \u062a\u0639\u0637\u064a\u0644 \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u062a\u062d\u062a\u064a\u0629\u060c \u0623\u0648 \u0627\u0644\u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0639\u0643\u0633\u064a\u0629 \u0644\u0644\u0643\u0648\u062f\u060c \u0623\u0648 \u0645\u062d\u0627\u0648\u0644\u0629 \u0627\u0633\u062a\u063a\u0644\u0627\u0644 \u0623\u064a \u062b\u063a\u0631\u0629 \u0628\u0631\u0645\u062c\u064a\u0629.</li>\n      <li>\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0623\u062f\u0648\u0627\u062a \u0622\u0644\u064a\u0629 \u0623\u0648 \u0628\u0631\u0627\u0645\u062c \u0631\u0648\u0628\u0648\u062a (Bots / Scrapers) \u0644\u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0623\u0648 \u0627\u0644\u062a\u0644\u0627\u0639\u0628 \u0628\u0646\u0642\u0627\u0637 \u0627\u0644\u062a\u0642\u064a\u064a\u0645 (MMR) \u0641\u064a \u0644\u0648\u062d\u0629 \u0627\u0644\u0634\u0631\u0641.</li>\n      <li>\u0643\u062a\u0627\u0628\u0629 \u0646\u0635\u0648\u0635 \u063a\u064a\u0631 \u0644\u0627\u0626\u0642\u0629\u060c \u0623\u0648 \u0645\u0633\u064a\u0626\u0629\u060c \u0623\u0648 \u062a\u0646\u062a\u0647\u0643 \u062d\u0642\u0648\u0642 \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0627\u0644\u0641\u0643\u0631\u064a\u0629 \u0641\u064a \u0642\u0633\u0645 \u0627\u0644\u0645\u0642\u0627\u0644\u0627\u062a \u0648\u0627\u0644\u064a\u0648\u0645\u064a\u0627\u062a \u0627\u0644\u0645\u0648\u062c\u0647\u0629 \u0644\u0644\u062a\u0635\u062d\u064a\u062d \u0627\u0644\u0622\u0644\u064a.</li>\n      <li>\u0645\u0634\u0627\u0631\u0643\u0629 \u0623\u0648 \u0628\u064a\u0639 \u0623\u0643\u0648\u0627\u062f \u0627\u0644\u062a\u0641\u0639\u064a\u0644 \u063a\u064a\u0631 \u0627\u0644\u0645\u062e\u0635\u0635\u0629 \u0644\u0643 \u0628\u0637\u0631\u0642 \u063a\u064a\u0631 \u0646\u0638\u0627\u0645\u064a\u0629.</li>\n    </ul>\n\n    <h2>3. \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0645\u0648\u0644\u062f \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a (AI-Generated Content)</h2>\n    <div class=\"card\">\n      <p>\n        \u062a\u0639\u062a\u0645\u062f \u0627\u0644\u0645\u0646\u0635\u0629 \u0639\u0644\u0649 \u0646\u0645\u0627\u0630\u062c \u0644\u063a\u0648\u064a\u0629 \u0645\u062a\u0642\u062f\u0645\u0629 (Google Gemini & Groq LPU) \u0644\u062a\u0648\u0644\u064a\u062f \u0642\u0637\u0639 \u0642\u0631\u0627\u0621\u0629 \u0648\u062a\u0641\u0633\u064a\u0631\u0627\u062a \u0648\u0634\u0631\u0648\u062d \u0639\u0627\u0645\u064a\u0629 \u0645\u0635\u0631\u064a\u0629:\n      </p>\n      <ul>\n        <li><strong>\u0627\u0644\u063a\u0631\u0636 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a:</strong> \u062c\u0645\u064a\u0639 \u0627\u0644\u0642\u0637\u0639 \u0648\u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0648\u0627\u0644\u062a\u062d\u0644\u064a\u0644\u0627\u062a \u0627\u0644\u0646\u062d\u0648\u064a\u0629 \u0648\u0627\u0644\u0645\u0639\u062c\u0645\u064a\u0629 \u0645\u0648\u0644\u062f\u0629 \u0644\u0623\u063a\u0631\u0627\u0636 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0648\u0627\u0644\u062a\u0623\u0647\u064a\u0644 \u0644\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0641\u0642\u0637.</li>\n        <li><strong>\u0627\u0644\u062f\u0642\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629:</strong> \u0646\u0633\u0639\u0649 \u062f\u0627\u0626\u0645\u0627\u064b \u0644\u0623\u0639\u0644\u0649 \u062f\u0631\u062c\u0627\u062a \u0627\u0644\u062f\u0642\u0629\u060c \u0648\u0644\u0643\u0646 \u0646\u0638\u0631\u0627\u064b \u0644\u0644\u0637\u0628\u064a\u0639\u0629 \u0627\u0644\u0627\u062d\u062a\u0645\u0627\u0644\u064a\u0629 \u0644\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a\u060c \u0646\u0646\u0635\u062d \u0628\u0627\u0644\u0631\u062c\u0648\u0639 \u0644\u0644\u0645\u0639\u0644\u0645 \u0639\u0646\u062f \u0627\u0644\u062d\u0627\u062c\u0629 \u0644\u0627\u0633\u062a\u064a\u0636\u0627\u062d \u0623\u064a \u0642\u0627\u0639\u062f\u0629 \u062e\u0644\u0627\u0641\u064a\u0629.</li>\n      </ul>\n    </div>\n\n    <h2>4. \u0623\u0643\u0648\u0627\u062f \u0627\u0644\u062a\u0641\u0639\u064a\u0644 \u0648\u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643\u0627\u062a \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629</h2>\n    <ul>\n      <li>\u062a\u064f\u0645\u0646\u062d \u0623\u0643\u0648\u0627\u062f \u0627\u0644\u062a\u0641\u0639\u064a\u0644 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u0645\u0639\u0644\u0645\u064a\u0646 \u0623\u0648 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0646\u0635\u0629 \u0648\u062a\u062a\u064a\u062d \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0645\u064a\u0632\u0627\u062a \u0645\u062a\u0642\u062f\u0645\u0629 \u0623\u0648 \u0627\u0644\u0627\u0646\u0636\u0645\u0627\u0645 \u0644\u0641\u0635\u0648\u0644 \u0645\u0639\u064a\u0646\u0629.</li>\n      <li>\u0643\u0644 \u0643\u0648\u062f \u062a\u0641\u0639\u064a\u0644 \u0635\u0627\u0644\u062d \u0644\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0645\u062d\u062f\u062f \u0644\u0647 \u0648\u0644\u0627 \u064a\u062c\u0648\u0632 \u0625\u0639\u0627\u062f\u0629 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647 \u0628\u0639\u062f \u062a\u0641\u0639\u064a\u0644\u0647 \u0628\u0646\u062c\u0627\u062d.</li>\n    </ul>\n\n    <h2>5. \u062d\u0642\u0648\u0642 \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0627\u0644\u0641\u0643\u0631\u064a\u0629 (Intellectual Property)</h2>\n    <p>\n      \u062c\u0645\u064a\u0639 \u062d\u0642\u0648\u0642 \u0627\u0644\u0646\u0634\u0631 \u0648\u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u062a\u062c\u0627\u0631\u064a\u0629 \u0648\u0627\u0644\u062a\u0635\u0645\u064a\u0645\u0627\u062a \u0648\u0627\u0644\u0647\u0648\u064a\u0629 \u0627\u0644\u0628\u0635\u0631\u064a\u0629 \u0648\u0646\u0638\u0645 \u0627\u0644\u062e\u0648\u0627\u0631\u0632\u0645\u064a\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u062a\u0637\u0628\u064a\u0642 \u00ab\u0642\u0637\u0639\u0647\u00bb \u0647\u064a \u0645\u0644\u0643 \u062d\u0635\u0631\u064a \u0644\u0645\u0637\u0648\u0631\u064a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 (zed32 devs / abo wehidy). \u0644\u0627 \u064a\u062c\u0648\u0632 \u0646\u0633\u062e \u0623\u0648 \u062a\u0648\u0632\u064a\u0639 \u0623\u064a \u062c\u0632\u0621 \u0645\u0646 \u0627\u0644\u0645\u0646\u0635\u0629 \u062f\u0648\u0646 \u0625\u0630\u0646 \u062e\u0637\u064a \u0645\u0633\u0628\u0642.\n    </p>\n\n    <h2>6. \u0625\u062e\u0644\u0627\u0621 \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0648\u062d\u062f\u0648\u062f \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645</h2>\n    <p>\n      \u064a\u062a\u0645 \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \"\u0643\u0645\u0627 \u0647\u0648\" (AS IS) \u062f\u0648\u0646 \u0636\u0645\u0627\u0646\u0627\u062a \u0635\u0631\u064a\u062d\u0629 \u0623\u0648 \u0636\u0645\u0646\u064a\u0629 \u0628\u0627\u0633\u062a\u0645\u0631\u0627\u0631 \u0627\u0644\u062e\u062f\u0645\u0629 \u062f\u0648\u0646 \u0623\u064a \u0627\u0646\u0642\u0637\u0627\u0639 \u0637\u0627\u0631\u0626 \u0646\u0627\u062c\u0645 \u0639\u0646 \u0635\u064a\u0627\u0646\u0629 \u0623\u0648 \u0623\u0639\u0637\u0627\u0644 \u0641\u064a \u0627\u0644\u0634\u0628\u0643\u0629 \u0627\u0644\u062f\u0648\u0644\u064a\u0629. \u0646\u062d\u0646 \u063a\u064a\u0631 \u0645\u0633\u0624\u0648\u0644\u064a\u0646 \u0639\u0646 \u0623\u064a \u0623\u0636\u0631\u0627\u0631 \u063a\u064a\u0631 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u0646\u0634\u0623 \u0639\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0623\u0648 \u0639\u062f\u0645 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642.\n    </p>\n\n    <h2>7. \u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u062e\u062f\u0645\u0629 \u0648\u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628</h2>\n    <p>\n      \u0646\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u062d\u0642 \u0641\u064a \u062a\u0639\u0644\u064a\u0642 \u0623\u0648 \u0625\u0646\u0647\u0627\u0621 \u062d\u0633\u0627\u0628 \u0623\u064a \u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u062e\u0627\u0644\u0641 \u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0648\u0637 \u0628\u0634\u0643\u0644 \u062c\u0648\u0647\u0631\u064a. \u0643\u0645\u0627 \u064a\u062d\u0642 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u062a\u0648\u0642\u0641 \u0639\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062e\u062f\u0645\u0629 \u0648\u0637\u0644\u0628 \u062d\u0630\u0641 \u062d\u0633\u0627\u0628\u0647 \u0648\u0628\u064a\u0627\u0646\u0627\u062a\u0647 \u0641\u064a \u0623\u064a \u0648\u0642\u062a \u0639\u0628\u0631 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u0648 \u0627\u0644\u0645\u0648\u0642\u0639.\n    </p>\n\n    <h2>8. \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0648\u0627\u062c\u0628 \u0627\u0644\u062a\u0637\u0628\u064a\u0642</h2>\n    <p>\n      \u062a\u062e\u0636\u0639 \u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0648\u0637 \u0648\u062a\u064f\u0641\u0633\u0631 \u0648\u0641\u0642\u0627\u064b \u0644\u0644\u0642\u0648\u0627\u0646\u064a\u0646 \u0627\u0644\u0645\u0639\u0645\u0648\u0644 \u0628\u0647\u0627 \u0641\u064a \u062c\u0645\u0647\u0648\u0631\u064a\u0629 \u0645\u0635\u0631 \u0627\u0644\u0639\u0631\u0628\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0627\u0644\u062a\u0627\u0645 \u0628\u0625\u0631\u0634\u0627\u062f\u0627\u062a \u0648\u0644\u0648\u0627\u0626\u062d \u0645\u062a\u062c\u0631 Google Play \u0644\u0645\u0637\u0648\u0631\u064a \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u0627\u062a.\n    </p>\n\n    <div class=\"contact-card\">\n      <h3 style=\"color: #fff; margin-bottom: 8px;\">\u0644\u0644\u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0648\u0627\u0644\u062f\u0639\u0645</h3>\n      <p style=\"margin-bottom: 12px;\">\u064a\u0633\u0639\u062f\u0646\u0627 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0643 \u0639\u0628\u0631 \u0642\u0646\u0648\u0627\u062a \u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0631\u0633\u0645\u064a\u0629:</p>\n      <p style=\"font-size: 16px;\">\n        \ud83d\udce7 \u0627\u0644\u062f\u0639\u0645: <a href=\"mailto:support@qataly.app\">support@qataly.app</a> | <a href=\"mailto:mmooup67@gmail.com\">mmooup67@gmail.com</a>\n      </p>\n    </div>\n  </main>\n\n  <footer>\n    <p>\u00a9 2026 \u062a\u0637\u0628\u064a\u0642 \u0642\u064e\u0637\u0652\u0639\u064e\u0644\u0650\u064a (Qata'ly). \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0642\u0648\u0642 \u0645\u062d\u0641\u0648\u0638\u0629 \u2014 \u062a\u0637\u0648\u064a\u0631 zed32 devs / abo wehidy</p>\n  </footer>\n\n</body>\n</html>\n";
const deleteAccountHtml = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>\u0637\u0644\u0628 \u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u2014 \u062a\u0637\u0628\u064a\u0642 \u0642\u0637\u0639\u0647 (Qata'ly)</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&family=Inter:wght@400;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --bg: #0A0E27;\n      --card-bg: #131B3E;\n      --card-border: #2A3875;\n      --accent-red: #EF4444;\n      --accent-blue: #229ED9;\n      --accent-cyan: #38BDF8;\n      --text-main: #FFFFFF;\n      --text-muted: #94A3B8;\n      --text-dim: #64748B;\n    }\n    * { margin: 0; padding: 0; box-sizing: border-box; }\n    body {\n      background-color: var(--bg);\n      color: var(--text-main);\n      font-family: 'Cairo', 'Inter', -apple-system, sans-serif;\n      line-height: 1.8;\n      padding: 0 16px 60px;\n    }\n    header {\n      max-width: 860px;\n      margin: 0 auto;\n      padding: 40px 0 24px;\n      text-align: center;\n      border-bottom: 2px solid var(--card-border);\n    }\n    .logo {\n      font-size: 38px;\n      font-weight: 900;\n      color: #fff;\n      display: inline-block;\n      margin-bottom: 8px;\n    }\n    .tagline {\n      color: var(--accent-cyan);\n      font-size: 15px;\n      font-weight: 700;\n    }\n    .nav-links {\n      display: flex;\n      justify-content: center;\n      gap: 12px;\n      margin-top: 20px;\n      flex-wrap: wrap;\n    }\n    .nav-links a {\n      color: var(--text-muted);\n      text-decoration: none;\n      font-size: 13px;\n      font-weight: 700;\n      padding: 6px 14px;\n      border: 1px solid var(--card-border);\n      border-radius: 8px;\n      background: var(--card-bg);\n      transition: all 0.2s;\n    }\n    .nav-links a:hover, .nav-links a.active {\n      color: #fff;\n      border-color: var(--accent-red);\n      background: rgba(239, 68, 68, 0.15);\n    }\n    main {\n      max-width: 860px;\n      margin: 32px auto 0;\n    }\n    .meta-badge {\n      display: inline-block;\n      background: rgba(239, 68, 68, 0.15);\n      border: 1px solid rgba(239, 68, 68, 0.4);\n      color: #FCA5A5;\n      font-size: 12px;\n      font-weight: 700;\n      padding: 4px 12px;\n      border-radius: 6px;\n      margin-bottom: 20px;\n    }\n    h1 {\n      font-size: 28px;\n      font-weight: 900;\n      margin-bottom: 12px;\n      color: #fff;\n    }\n    h2 {\n      font-size: 20px;\n      font-weight: 800;\n      margin: 36px 0 14px;\n      color: var(--accent-cyan);\n      border-right: 4px solid var(--accent-red);\n      padding-right: 12px;\n    }\n    p, li {\n      color: var(--text-muted);\n      font-size: 15px;\n      margin-bottom: 14px;\n    }\n    ul, ol {\n      padding-right: 24px;\n      margin-bottom: 16px;\n    }\n    li { margin-bottom: 8px; }\n    .card {\n      background: var(--card-bg);\n      border: 1.5px solid var(--card-border);\n      border-radius: 14px;\n      padding: 24px;\n      margin: 20px 0;\n    }\n    .alert-danger {\n      background: rgba(239, 68, 68, 0.1);\n      border: 2px solid var(--accent-red);\n      border-radius: 12px;\n      padding: 20px;\n      margin: 24px 0;\n    }\n    .alert-danger h3 {\n      color: #F87171;\n      font-size: 17px;\n      margin-bottom: 8px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .step-box {\n      background: #0D1430;\n      border: 1px solid var(--card-border);\n      border-radius: 10px;\n      padding: 16px 20px;\n      margin-bottom: 14px;\n    }\n    .step-number {\n      background: var(--accent-blue);\n      color: #fff;\n      font-weight: 900;\n      font-size: 12px;\n      padding: 2px 8px;\n      border-radius: 4px;\n      margin-left: 8px;\n    }\n    .form-group {\n      margin-bottom: 18px;\n      text-align: right;\n    }\n    label {\n      display: block;\n      margin-bottom: 6px;\n      font-weight: 700;\n      color: #fff;\n      font-size: 14px;\n    }\n    input, textarea {\n      width: 100%;\n      padding: 12px 14px;\n      background: #0A0E27;\n      border: 1.5px solid var(--card-border);\n      border-radius: 8px;\n      color: #fff;\n      font-family: inherit;\n      font-size: 14px;\n    }\n    input:focus, textarea:focus {\n      outline: none;\n      border-color: var(--accent-cyan);\n    }\n    .submit-btn {\n      background: var(--accent-red);\n      color: #fff;\n      border: none;\n      padding: 14px 28px;\n      font-size: 15px;\n      font-weight: 900;\n      border-radius: 8px;\n      cursor: pointer;\n      width: 100%;\n      transition: background 0.2s;\n    }\n    .submit-btn:hover {\n      background: #DC2626;\n    }\n    footer {\n      max-width: 860px;\n      margin: 50px auto 0;\n      text-align: center;\n      font-size: 12px;\n      color: var(--text-dim);\n      border-top: 1px solid var(--card-border);\n      padding-top: 24px;\n    }\n  </style>\n</head>\n<body>\n\n  <header>\n    <div class=\"logo\">\u0642\u064e\u0637\u0652\u0639\u064e\u0644\u0650\u064a \u26a1 (Qata'ly)</div>\n    <div class=\"tagline\">\u0637\u0644\u0628 \u0648\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u2014 \u0645\u062a\u0648\u0627\u0641\u0642 \u0645\u0639 \u0645\u0639\u0627\u064a\u064a\u0631 Google Play</div>\n    <nav class=\"nav-links\">\n      <a href=\"/functions/v1/legal\">\u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629</a>\n      <a href=\"/functions/v1/legal/privacy\">\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629</a>\n      <a href=\"/functions/v1/legal/terms\">\u0634\u0631\u0648\u0637 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645</a>\n      <a href=\"/functions/v1/legal/delete-account\" class=\"active\">\u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a</a>\n      <a href=\"/functions/v1/legal/licenses\">\u0627\u0644\u062a\u0631\u0627\u062e\u064a\u0635 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629</a>\n    </nav>\n  </header>\n\n  <main>\n    <span class=\"meta-badge\">\u0633\u064a\u0627\u0633\u0629 \u0623\u0645\u0627\u0646 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a (Google Play Data Safety)</span>\n    <h1>\u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629</h1>\n\n    <p>\n      \u0627\u062d\u062a\u0631\u0627\u0645\u0627\u064b \u0644\u062e\u0635\u0648\u0635\u064a\u062a\u0643 \u0648\u062d\u0642\u0643 \u0641\u064a \u0627\u0644\u062a\u062d\u0643\u0645 \u0627\u0644\u0643\u0627\u0645\u0644 \u0628\u0628\u064a\u0627\u0646\u0627\u062a\u0643 (Right to Erasure)\u060c \u064a\u062a\u064a\u062d \u062a\u0637\u0628\u064a\u0642 <strong>\u00ab\u0642\u0637\u0639\u0647\u00bb (Qata'ly)</strong> \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u062d\u0630\u0641 \u062d\u0633\u0627\u0628\u0627\u062a\u0647\u0645 \u0648\u062c\u0645\u064a\u0639 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0647\u0627 \u0641\u064a \u0623\u064a \u0648\u0642\u062a \u0648\u0628\u0643\u0644 \u0633\u0647\u0648\u0644\u0629.\n    </p>\n\n    <div class=\"alert-danger\">\n      <h3>\u26a0\ufe0f \u062a\u0646\u0628\u064a\u0647 \u0647\u0627\u0645 \u0642\u0628\u0644 \u0627\u0644\u062d\u0630\u0641:</h3>\n      <p style=\"color: #FECACA; margin: 0;\">\n        \u0639\u0645\u0644\u064a\u0629 \u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0646\u0647\u0627\u0626\u064a\u0629 \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646\u0647\u0627. \u0633\u064a\u062a\u0645 \u062d\u0630\u0641 \u062a\u0642\u064a\u064a\u0645\u0643 (MMR)\u060c \u0648\u0633\u062c\u0644 \u062d\u0644\u0648\u0644 \u0627\u0644\u0642\u0637\u0639\u060c \u0648\u0642\u0627\u0645\u0648\u0633 \u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0635\u0639\u0628\u0629\u060c \u0648\u0627\u0644\u062a\u062a\u0627\u0628\u0639 \u0627\u0644\u064a\u0648\u0645\u064a (Streak)\u060c \u0648\u0644\u0646 \u062a\u062a\u0645\u0643\u0646 \u0645\u0646 \u0627\u0633\u062a\u0639\u0627\u062f\u0629 \u0647\u0630\u0627 \u0627\u0644\u062a\u0642\u062f\u0645 \u0644\u0627\u062d\u0642\u0627\u064b.\n      </p>\n    </div>\n\n    <h2>\u0623\u0648\u0644\u0627\u064b: \u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0645\u0628\u0627\u0634\u0631\u0629 \u0645\u0646 \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 (In-App Deletion)</h2>\n    <p>\u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u062b\u0628\u062a\u0627\u064b \u0639\u0644\u0649 \u0647\u0627\u062a\u0641\u0643\u060c \u064a\u0645\u0643\u0646\u0643 \u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u062d\u0630\u0641 \u0627\u0644\u0641\u0648\u0631\u064a \u0628\u062e\u0637\u0648\u0627\u062a \u0628\u0633\u064a\u0637\u0629:</p>\n    \n    <div class=\"step-box\">\n      <p style=\"color: #fff; margin: 0;\"><span class=\"step-number\">1</span> \u0627\u0641\u062a\u062d \u062a\u0637\u0628\u064a\u0642 <strong>\u0642\u0637\u0639\u0647</strong> \u0639\u0644\u0649 \u0647\u0627\u062a\u0641\u0643 \u0648\u0633\u062c\u0644 \u0627\u0644\u062f\u062e\u0648\u0644.</p>\n    </div>\n    <div class=\"step-box\">\n      <p style=\"color: #fff; margin: 0;\"><span class=\"step-number\">2</span> \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u062a\u0628\u0648\u064a\u0628 <strong>\u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0634\u062e\u0635\u064a (\ud83d\udc64)</strong> \u0645\u0646 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0633\u0641\u0644\u064a\u0629.</p>\n    </div>\n    <div class=\"step-box\">\n      <p style=\"color: #fff; margin: 0;\"><span class=\"step-number\">3</span> \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u062e\u064a\u0627\u0631 <strong>\u00ab\u0627\u0644\u0634\u0631\u0648\u0637 \u0648\u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 \u0648\u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628\u00bb</strong>.</p>\n    </div>\n    <div class=\"step-box\">\n      <p style=\"color: #fff; margin: 0;\"><span class=\"step-number\">4</span> \u0627\u062e\u062a\u0631 \u062a\u0628\u0648\u064a\u0628 <strong>\u00ab\u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628\u00bb</strong> \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0632\u0631 <strong>\u00ab\u062a\u0623\u0643\u064a\u062f \u062d\u0630\u0641 \u062d\u0633\u0627\u0628\u064a \u0646\u0647\u0627\u0626\u064a\u0627\u064b \ud83d\uddd1\ufe0f\u00bb</strong>.</p>\n    </div>\n    <p style=\"color: var(--accent-cyan);\">\u26a1 \u0633\u064a\u062a\u0645 \u0645\u0633\u062d \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0645\u0646 \u062e\u0648\u0627\u062f\u0645 \u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0641\u0648\u0631\u0627\u064b \u0648\u062a\u0633\u062c\u064a\u0644 \u062e\u0631\u0648\u062c\u0643 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0644\u062d\u0638\u0629.</p>\n\n    <h2>\u062b\u0627\u0646\u064a\u0627\u064b: \u0637\u0644\u0628 \u0627\u0644\u062d\u0630\u0641 \u0639\u0628\u0631 \u0627\u0644\u0648\u064a\u0628 (\u0625\u0630\u0627 \u062d\u0630\u0641\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642)</h2>\n    <p>\u0625\u0630\u0627 \u0642\u0645\u062a \u0628\u0625\u0644\u063a\u0627\u0621 \u062a\u062b\u0628\u064a\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u062a\u0631\u063a\u0628 \u0641\u064a \u062d\u0630\u0641 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0645\u0646 \u062e\u0648\u0627\u062f\u0645\u0646\u0627\u060c \u064a\u0631\u062c\u0649 \u0625\u0631\u0633\u0627\u0644 \u0637\u0644\u0628 \u0627\u0644\u062d\u0630\u0641 \u0639\u0628\u0631 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u062a\u0627\u0644\u064a \u0623\u0648 \u0645\u0631\u0627\u0633\u0644\u062a\u0646\u0627 \u0628\u0627\u0644\u0628\u0631\u064a\u062f \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a:</p>\n\n    <div class=\"card\">\n      <form action=\"mailto:support@qataly.app?subject=Account%20Deletion%20Request%20-%20Qataly\" method=\"POST\" enctype=\"text/plain\">\n        <div class=\"form-group\">\n          <label>\u0645\u0639\u0631\u0641 \u0627\u0644\u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 (Telegram ID \u0623\u0648 Username):</label>\n          <input type=\"text\" name=\"Telegram_ID\" placeholder=\"\u0645\u062b\u0627\u0644: @username \u0623\u0648 \u0631\u0642\u0645 \u0627\u0644\u062d\u0633\u0627\u0628\" required>\n        </div>\n\n        <div class=\"form-group\">\n          <label>\u0627\u0644\u0628\u0631\u064a\u062f \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u0644\u0644\u062a\u0623\u0643\u064a\u062f \u0648\u0627\u0644\u062a\u0648\u0627\u0635\u0644:</label>\n          <input type=\"email\" name=\"Contact_Email\" placeholder=\"your-email@example.com\" required>\n        </div>\n\n        <div class=\"form-group\">\n          <label>\u0633\u0628\u0628 \u0627\u0644\u062d\u0630\u0641 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a \u0644\u0645\u0633\u0627\u0639\u062f\u062a\u0646\u0627 \u0641\u064a \u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u062a\u062c\u0631\u0628\u0629):</label>\n          <textarea name=\"Reason\" rows=\"3\" placeholder=\"\u0627\u0643\u062a\u0628 \u0633\u0628\u0628 \u0631\u063a\u0628\u062a\u0643 \u0641\u064a \u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628...\"></textarea>\n        </div>\n\n        <button type=\"submit\" class=\"submit-btn\">\u0625\u0631\u0633\u0627\u0644 \u0637\u0644\u0628 \u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u2709\ufe0f</button>\n      </form>\n    </div>\n\n    <h2>\u062b\u0627\u0644\u062b\u0627\u064b: \u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062a\u0645 \u062d\u0630\u0641\u0647\u0627 \u0648\u0641\u062a\u0631\u0627\u062a \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638</h2>\n    <div class=\"card\">\n      <table style=\"width: 100%; border-collapse: collapse; text-align: right;\">\n        <thead>\n          <tr style=\"border-bottom: 2px solid var(--card-border);\">\n            <th style=\"padding: 10px; color: #fff;\">\u0646\u0648\u0639 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a</th>\n            <th style=\"padding: 10px; color: #fff;\">\u0627\u0644\u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u0645\u062a\u062e\u0630</th>\n            <th style=\"padding: 10px; color: #fff;\">\u0645\u062f\u0629 \u0627\u0644\u062a\u0646\u0641\u064a\u0630</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom: 1px solid var(--card-border);\">\n            <td style=\"padding: 10px; color: var(--text-muted);\">\u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0634\u062e\u0635\u064a \u0648\u0627\u0644\u0627\u0633\u0645 \u0648\u0631\u0642\u0645 \u0627\u0644\u0645\u0639\u0631\u0641</td>\n            <td style=\"padding: 10px; color: #34D399;\">\u062d\u0630\u0641 \u0641\u0648\u0631\u064a \u0648\u062f\u0627\u0626\u0645</td>\n            <td style=\"padding: 10px; color: var(--accent-cyan);\">\u0641\u0648\u0631\u064a (\u062e\u0644\u0627\u0644 \u062b\u0648\u0627\u0646\u064d)</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid var(--card-border);\">\n            <td style=\"padding: 10px; color: var(--text-muted);\">\u0633\u062c\u0644 \u062d\u0644 \u0627\u0644\u0642\u0637\u0639 \u0648\u062f\u0631\u062c\u0627\u062a \u0627\u0644\u062a\u0642\u064a\u064a\u0645 (MMR)</td>\n            <td style=\"padding: 10px; color: #34D399;\">\u062d\u0630\u0641 \u0643\u0627\u0645\u0644 \u0648\u0634\u0627\u0645\u0644</td>\n            <td style=\"padding: 10px; color: var(--accent-cyan);\">\u0641\u0648\u0631\u064a</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid var(--card-border);\">\n            <td style=\"padding: 10px; color: var(--text-muted);\">\u0642\u0627\u0645\u0648\u0633 \u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0635\u0639\u0628\u0629 (Weak Words)</td>\n            <td style=\"padding: 10px; color: #34D399;\">\u062d\u0630\u0641 \u0643\u0627\u0645\u0644 \u0648\u0634\u0627\u0645\u0644</td>\n            <td style=\"padding: 10px; color: var(--accent-cyan);\">\u0641\u0648\u0631\u064a</td>\n          </tr>\n          <tr>\n            <td style=\"padding: 10px; color: var(--text-muted);\">\u062c\u0644\u0633\u0627\u062a \u0627\u0644\u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u0645\u0624\u0642\u062a\u0629 (Sessions)</td>\n            <td style=\"padding: 10px; color: #34D399;\">\u0625\u0628\u0637\u0627\u0644 \u0648\u062d\u0630\u0641 \u0646\u0647\u0627\u0626\u064a</td>\n            <td style=\"padding: 10px; color: var(--accent-cyan);\">\u0641\u0648\u0631\u064a</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n\n    <p style=\"text-align: center; color: var(--text-dim); margin-top: 24px;\">\n      \u0644\u0623\u064a \u0645\u0633\u0627\u0639\u062f\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0623\u0648 \u0627\u0633\u062a\u0641\u0633\u0627\u0631 \u0625\u0636\u0627\u0641\u064a: <a href=\"mailto:support@qataly.app\" style=\"color: var(--accent-cyan);\">support@qataly.app</a>\n    </p>\n  </main>\n\n  <footer>\n    <p>\u00a9 2026 \u062a\u0637\u0628\u064a\u0642 \u0642\u064e\u0637\u0652\u0639\u064e\u0644\u0650\u064a (Qata'ly). \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0642\u0648\u0642 \u0645\u062d\u0641\u0648\u0638\u0629 \u2014 \u062a\u0637\u0648\u064a\u0631 zed32 devs / abo wehidy</p>\n  </footer>\n\n</body>\n</html>\n";
