Deno.serve(async (req: Request) => {
  const url = new URL(req.url);
  const path = url.pathname.toLowerCase();

  const headers = new Headers({
    'Content-Type': 'text/html; charset=utf-8',
    'Cache-Control': 'public, max-age=3600',
    'Access-Control-Allow-Origin': '*',
  });

  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers });
  }

  if (path.includes('/privacy')) {
    return new Response(privacyHtml, { headers });
  } else if (path.includes('/terms')) {
    return new Response(termsHtml, { headers });
  } else if (path.includes('/delete-account') || path.includes('/delete')) {
    return new Response(deleteAccountHtml, { headers });
  } else if (path.includes('/licenses') || path.includes('/license')) {
    return new Response(licensesHtml, { headers });
  }

  return new Response(hubHtml, { headers });
});
